import os
import torch


class Config:
    """
    Central configuration for the EfficientNetV2-S based animal classification task.
    """

    # =======================
    # General Configuration
    # =======================
    SEED = 42
    DEBUG = False  # Set to True to run on a small subset of data for debugging
    DEBUG_SAMPLE_SIZE = 1000  # Number of samples to use when DEBUG is True

    # =======================
    # File Paths
    # =======================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the metadata script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Image directories
    TRAIN_IMAGES_DIR = os.path.join(INPUT_ROOT, "train_images")
    TEST_IMAGES_DIR = os.path.join(INPUT_ROOT, "test_images")

    # Working directory for artifacts (checkpoints, cache)
    WORKING_DIR = "./working/idea_2"

    # Output paths
    MODEL_CHECKPOINT_PATH = os.path.join(WORKING_DIR, "efficientnetv2_s_best.pth")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =======================
    # Data Configuration
    # =======================
    IMAGE_SIZE = 256
    NUM_CLASSES = 23
    NUM_WORKERS = 4  # Optimized for 12 vCPUs

    # =======================
    # Model Configuration
    # =======================
    MODEL_NAME = "tf_efficientnetv2_s"  # timm model name
    PRETRAINED = True
    DROPOUT_RATE = 0.2
    DROP_PATH_RATE = 0.1

    # =======================
    # Training Configuration
    # =======================
    BATCH_SIZE = 64  # A100 40GB can handle this easily
    NUM_EPOCHS = 10
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Scheduler parameters (OneCycleLR)
    PCT_START = 0.3
    DIV_FACTOR = 25.0
    FINAL_DIV_FACTOR = 1000.0

    # =======================
    # Hardware
    # =======================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Ensures necessary directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Automatically setup directories when config is imported
Config.setup()
